def investigate(context, acquire):
    actions = context.get('actions', [])
    committed = set()
    pending = None
    high = 0
    for action in actions:
        op = action.get('op')
        if op == 'put':
            ident = action.get('id')
            if pending is None:
                committed.add(ident)
            else:
                pending.add(ident)
            if ident > high:
                high = ident
        elif op == 'delete':
            ident = action.get('id')
            if pending is None:
                committed.discard(ident)
            else:
                pending.discard(ident)
        elif op == 'begin':
            pending = set(committed)
        elif op == 'commit':
            committed = set(pending)
            pending = None
        elif op == 'rollback':
            pending = None
    return high + 1
